insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_apparently','apparently','adverb','according to what seems to be true or what people say, although it has not been confirmed','[{"senseId":"apparently_1","meaning":"according to what seems to be true or what people say, although it has not been confirmed","acceptedParaphrases":["seemingly","as it appears"],"masteryContexts":[{"contextId":"u2_11_apparently_meaning","text":"The singer has apparently left the band, but nobody has confirmed it.","meaning":"according to what people say, not confirmed","wrongMeanings":["according to the official announcement made today","because the other members asked him to go","as the band proudly announced last week"]},{"contextId":"u2_11_apparently_paraphrase","text":"The apparently empty room was full of sleeping cats.","meaning":"as it seemed at first sight","wrongMeanings":["as the owner had promised earlier","as an expert had measured it exactly","as had been proved by the records"]}],"situationDistractors":["The reporter checked three official records and confirmed the date.","A scientist proved the idea with a clear experiment.","A witness described exactly what she had seen with her own eyes.","The teacher checked the register and counted every student in the room.","A news reporter stood outside the stadium and described exactly what she was watching.","The headteacher read the official exam results aloud to the whole school."],"gapDistractors":[{"contextId":"u2_11_apparently_gap_1","answer":"apparently","wrong":["definitely","officially","certainly"]},{"contextId":"u2_11_apparently_gap_2","answer":"apparently","wrong":["personally","proudly","secretly"]},{"contextId":"u2_11_apparently_gap_3","answer":"apparently","wrong":["certainly","officially","definitely"]}],"spellingErrors":["apparantly","aparently","apparentlly","apparrently","apperently","aparrently"],"masteryPassages":[{"passageId":"u2_11_apparently_passage_1","contextId":"u2_11_apparently_gap_1","text":"Mia did not see the game herself, so she cannot be sure of anything. She heard from a classmate that, ____, the home team lost by two goals.","answer":"apparently"},{"passageId":"u2_11_apparently_passage_2","contextId":"u2_11_apparently_gap_2","text":"From the street, the shop looked busy and bright. Inside, however, the ____ popular café was nearly empty, and the owner was reading a newspaper.","answer":"apparently"}],"contextDependentParaphrases":[],"wrongParaphrases":["definitely","recently","secretly"],"misleadingDistractors":["obviously, with no doubt at all","after a long time","in a very careful way"]}]'::jsonb,'[]'::jsonb,'["apparently unaware","apparently simple","apparently true"]'::jsonb,'live'),
('vocab_supposedly','supposedly','adverb','according to what many people believe or say, although it may not be true','[{"senseId":"supposedly_1","meaning":"according to what many people believe or say, although it may not be true","acceptedParaphrases":["allegedly","reportedly"],"masteryContexts":[{"contextId":"u2_12_supposedly_meaning","text":"The film is supposedly based on a true story, but many details are invented.","meaning":"said to be true, but doubted","wrongMeanings":["proved to be true by the evidence","agreed to be true by all the critics","confirmed as true by the director"]},{"contextId":"u2_12_supposedly_paraphrase","text":"He is supposedly a great cook, though I have never tasted his food.","meaning":"according to what people claim","wrongMeanings":["according to what I have seen myself","according to the official restaurant guide","according to a test I carried out"]}],"situationDistractors":["The inspector tested the machine and proved that it worked perfectly.","She saw the accident with her own eyes and described it to the police.","The brochure listed the exact opening times of the museum.","The chef tasted every dish himself and checked that the flavours were right.","A scientist repeated the experiment three times and recorded every result in a table.","The museum guide pointed to the signed document and explained exactly when it had been written."],"gapDistractors":[{"contextId":"u2_12_supposedly_gap_1","answer":"supposedly","wrong":["clearly","certainly","definitely"]},{"contextId":"u2_12_supposedly_gap_2","answer":"supposedly","wrong":["obviously","undoubtedly","certainly"]},{"contextId":"u2_12_supposedly_gap_3","answer":"supposedly","wrong":["definitely","clearly","undoubtedly"]}],"spellingErrors":["supposidly","suposedly","supposeddly","suppossedly","supposebly","supposadly"],"wordFamilyForms":[{"form":"supposedly","partOfSpeech":"adverb","example":"The old well is supposedly the oldest in the village, though nobody has checked.","pedagogicallyUseful":true},{"form":"suppose","partOfSpeech":"verb","example":"I suppose the shop will be closed by now.","pedagogicallyUseful":true,"altExample":"Let us suppose that every student had a laptop; how would lessons change?"},{"form":"supposed","partOfSpeech":"adjective","example":"The supposed expert had never actually studied the subject.","pedagogicallyUseful":true,"altExample":"The supposed benefits of the diet were never proved."}],"masteryPassages":[{"passageId":"u2_12_supposedly_passage_1","contextId":"u2_12_supposedly_gap_1","text":"The leaflet says the herbal tea cures every illness. Our science teacher laughed and asked for proof, because a drink that is ____ so powerful ought to be tested properly.","answer":"supposedly"},{"passageId":"u2_12_supposedly_passage_2","contextId":"u2_12_supposedly_gap_2","text":"The café is ____ the cheapest in the city, and it has a huge sign outside to say so. Yet my friends and I paid more there than anywhere else.","answer":"supposedly"}],"contextDependentParaphrases":[],"wrongParaphrases":["definitely","deliberately","officially"],"misleadingDistractors":["definitely and proven","on purpose","as quickly as possible"]}]'::jsonb,'["suppose","supposed"]'::jsonb,'["supposedly safe","supposedly harmless","supposedly healthy"]'::jsonb,'live'),
('vocab_celebrity','celebrity','noun','a famous person, especially in entertainment or sport','[{"senseId":"celebrity_1","meaning":"a famous person, especially in entertainment or sport","acceptedParaphrases":["famous person","star"],"masteryContexts":[{"contextId":"u2_13_celebrity_meaning","text":"The celebrity was surrounded by photographers outside the hotel.","meaning":"a famous person","wrongMeanings":["a person who owns the hotel","a person who works at the hotel","a person who is staying alone"]},{"contextId":"u2_13_celebrity_paraphrase","text":"The charity asked a celebrity to support its campaign.","meaning":"someone well known from entertainment or sport","wrongMeanings":["someone skilled at designing posters","someone employed by the local council","someone who has just left school"]}],"situationDistractors":["A baker who is well liked by everyone on her street opened a second shop.","An engineer won a national award that few people ever heard about.","The headteacher gave a speech to the parents in the school hall.","A shy student won the school science prize and was congratulated by her class.","A university professor gave a lecture on climate change to a hall of two hundred people.","The school choir performed at the town hall, and parents took photographs of their own children."],"gapDistractors":[{"contextId":"u2_13_celebrity_gap_1","answer":"celebrity","wrong":["neighbour","accountant","plumber"]},{"contextId":"u2_13_celebrity_gap_2","answer":"celebrity","wrong":["neighbour","plumber","librarian"]},{"contextId":"u2_13_celebrity_gap_3","answer":"celebrity","wrong":["librarian","neighbour","dentist"]}],"spellingErrors":["celebrety","celibrity","celebritty","celabrity","celebraty","celebirty"],"masteryPassages":[{"passageId":"u2_13_celebrity_passage_1","contextId":"u2_13_celebrity_gap_1","text":"Hundreds of fans gathered outside the theatre, holding posters and phones. When the ____ finally stepped out of the car, the crowd screamed and photographers began taking pictures.","answer":"celebrity"},{"passageId":"u2_13_celebrity_passage_2","contextId":"u2_13_celebrity_gap_2","text":"Brands often pay a singer or footballer to appear in their adverts. They hope that customers will trust a product more if a ____ is seen using it.","answer":"celebrity"}],"contextDependentParaphrases":[],"wrongParaphrases":["skilled worker","school leader","online shopper"],"misleadingDistractors":["a public party","a person who works behind the scenes","a prize for winning"]}]'::jsonb,'[]'::jsonb,'["celebrity chef","celebrity status","young celebrity"]'::jsonb,'live'),
('vocab_informed','informed','adjective','having or showing knowledge about a subject or situation','[{"senseId":"informed_1","meaning":"having or showing knowledge about a subject or situation","acceptedParaphrases":["knowledgeable","aware"],"masteryContexts":[{"contextId":"u2_14_informed_meaning","text":"She made an informed decision after reading all the reports.","meaning":"based on knowledge and the facts","wrongMeanings":["made quickly without any discussion","made by a group of friends","made to please her teachers"]},{"contextId":"u2_14_informed_paraphrase","text":"Keep your parents informed about where you are.","meaning":"told about what is happening","wrongMeanings":["asked for permission about everything","warned about what to avoid","corrected about what is wrong"]}],"situationDistractors":["The student guessed the answer without reading the question.","He chose a phone because it was the cheapest one in the shop.","The committee voted quickly without reading the report.","He bought the first laptop he saw because the sales assistant was friendly.","The committee voted on the proposal after a very short discussion and without checking the figures.","She copied her friend’s opinion on the topic because she had not read the article herself."],"gapDistractors":[{"contextId":"u2_14_informed_gap_1","answer":"informed","wrong":["emotional","sudden","hasty"]},{"contextId":"u2_14_informed_gap_2","answer":"informed","wrong":["angry","anxious","eager"]},{"contextId":"u2_14_informed_gap_3","answer":"informed","wrong":["unaware","uncertain","confused"]}],"spellingErrors":["infomed","informd","enformed","inforrmed","informmed","imformed"],"wordFamilyForms":[{"form":"informed","partOfSpeech":"adjective","example":"The article helps readers make an informed choice about their diet.","pedagogicallyUseful":true},{"form":"inform","partOfSpeech":"verb","example":"Please inform the office if you are going to be absent.","pedagogicallyUseful":true},{"form":"information","partOfSpeech":"noun","example":"The website provides useful information about courses.","pedagogicallyUseful":true},{"form":"informative","partOfSpeech":"adjective","example":"The museum guide was friendly and very informative.","pedagogicallyUseful":true},{"form":"uninformed","partOfSpeech":"adjective","example":"Many people hold uninformed opinions about the topic.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_14_informed_passage_1","contextId":"u2_14_informed_gap_1","text":"Before voting in the school election, Tariq read each candidate’s plan and asked them questions. As a result, he felt he was making a properly ____ choice.","answer":"informed"},{"passageId":"u2_14_informed_passage_2","contextId":"u2_14_informed_gap_2","text":"The head teacher believes that parents should hear about every change to the timetable. She writes a weekly email so that families stay ____.","answer":"informed"}],"contextDependentParaphrases":[],"wrongParaphrases":["anxious","generous","certain"],"misleadingDistractors":["told off for bad behaviour","given a prize","confused and worried"]}]'::jsonb,'["inform","information","informative","uninformed"]'::jsonb,'["well informed","stay informed","informed choice"]'::jsonb,'live'),
('vocab_admit','admit','verb','to agree, often unwillingly, that something is true','[{"senseId":"admit_1","meaning":"to agree, often unwillingly, that something is true","acceptedParaphrases":["confess","accept that it is true"],"masteryContexts":[{"contextId":"u2_15_admit_meaning","text":"I admit that I made a mistake.","meaning":"agree that something is true, often unwillingly","wrongMeanings":["explain why something was done","promise that it will not happen again","believe that something is not important"]},{"contextId":"u2_15_admit_paraphrase","text":"Politicians rarely admit responsibility when something goes wrong.","meaning":"accept that you are to blame","wrongMeanings":["refuse to speak about a problem","promise to solve a problem quickly","blame other people for a problem"]}],"situationDistractors":["He insisted that he had never been near the shop.","She refused to say who had taken the money.","The boy explained that the dog had eaten his homework.","The player argued with the referee and insisted that the ball had never crossed the line.","Nobody in the class could remember who had left the door open, and they all looked puzzled.","The manager praised the team for their hard work and announced a day off."],"gapDistractors":[{"contextId":"u2_15_admit_gap_1","answer":"admit","wrong":["imagine","predict","notice"]},{"contextId":"u2_15_admit_gap_2","answer":"admit","wrong":["pretend","deny","hope"]},{"contextId":"u2_15_admit_gap_3","answer":"admit","wrong":["predict","promise","request"]}],"spellingErrors":["admitt","admet","ammit","admmit","adimit","admite"],"wordFamilyForms":[{"form":"admit","partOfSpeech":"verb","example":"Few people find it easy to admit that they were wrong.","pedagogicallyUseful":true},{"form":"admission","partOfSpeech":"noun","example":"His admission that he had copied the answers surprised his teachers.","pedagogicallyUseful":true,"altExample":"The company’s admission of responsibility came after months of denial.","note":"The \"entrance fee\" sense of admission is a separate meaning and is not taught here."},{"form":"admittedly","partOfSpeech":"adverb","example":"The plan is expensive and, admittedly, rather risky.","pedagogicallyUseful":true,"altExample":"The film is long and, admittedly, a little slow, but I enjoyed it."}],"masteryPassages":[{"passageId":"u2_15_admit_passage_1","contextId":"u2_15_admit_gap_1","text":"The manager stared at the broken window, and the boy looked at his shoes. After a long silence, he decided to ____ that the ball had been his.","answer":"admit"},{"passageId":"u2_15_admit_passage_2","contextId":"u2_15_admit_gap_2","text":"Nobody likes being wrong in front of others. Still, a good scientist is willing to ____ when the results do not support her idea.","answer":"admit"}],"contextDependentParaphrases":[],"wrongParaphrases":["complain","announce","insist"],"misleadingDistractors":["deny that it happened","forget completely","announce proudly"]}]'::jsonb,'["admission","admittedly"]'::jsonb,'["admit defeat","freely admit","admit responsibility"]'::jsonb,'live'),
('vocab_communicate','communicate','verb','to share information, ideas or feelings with other people','[{"senseId":"communicate_1","meaning":"to share information, ideas or feelings with other people","acceptedParaphrases":["share information","exchange ideas"],"masteryContexts":[{"contextId":"u2_16_communicate_meaning","text":"Good leaders communicate their plans clearly.","meaning":"share information or ideas so others understand","wrongMeanings":["keep information or ideas secret from others","change information or ideas to suit others","copy information or ideas from others"]},{"contextId":"u2_16_communicate_paraphrase","text":"Dolphins communicate using clicks and whistles.","meaning":"exchange information using signals","wrongMeanings":["copy their trainers using signals","learn new tricks using signals","follow orders using signals"]}],"situationDistractors":["She kept her plans secret from the rest of the team.","The two friends sat in silence on the bus, each reading a book.","He travelled to another city to start a new job.","Every evening, the old man sat alone on the bench and watched the ducks on the lake.","The students worked silently on their own exercises, and nobody asked any questions.","The two neighbours lived next door for years but never spoke to each other."],"gapDistractors":[{"contextId":"u2_16_communicate_gap_1","answer":"communicate","wrong":["behave","compete","bargain"]},{"contextId":"u2_16_communicate_gap_2","answer":"communicate","wrong":["hide","translate","invent"]},{"contextId":"u2_16_communicate_gap_3","answer":"communicate","wrong":["behave","smile","play"]}],"spellingErrors":["comunicate","communcate","communikate","comunnicate","communicat","comminicate"],"wordFamilyForms":[{"form":"communicate","partOfSpeech":"verb","example":"Scientists need to communicate their findings clearly to the public.","pedagogicallyUseful":true},{"form":"communication","partOfSpeech":"noun","example":"Good communication between teachers and parents prevents many problems.","pedagogicallyUseful":true},{"form":"communicator","partOfSpeech":"noun","example":"She is an excellent communicator who explains complex ideas simply.","pedagogicallyUseful":true},{"form":"communicative","partOfSpeech":"adjective","example":"After a few months abroad, the shy boy became far more communicative.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u2_16_communicate_passage_1","contextId":"u2_16_communicate_gap_1","text":"Pilots and air traffic controllers use short, standard phrases on the radio. This helps them to ____ quickly and without misunderstandings, even when the weather is terrible.","answer":"communicate"},{"passageId":"u2_16_communicate_passage_2","contextId":"u2_16_communicate_gap_2","text":"My cousin lives in Canada, and we are eight hours apart. We usually ____ by sending voice messages, because it is hard to find a time when we are both awake.","answer":"communicate"}],"contextDependentParaphrases":[],"wrongParaphrases":["hide information","collect information","delete information"],"misleadingDistractors":["hide information from others","travel to another country","argue loudly"]}]'::jsonb,'["communication","communicator","communicative"]'::jsonb,'["communicate effectively","communicate clearly","communicate online"]'::jsonb,'live'),
('vocab_remotely','remotely','adverb','from a distance, without being physically present, usually by using technology','[{"senseId":"remotely_1","meaning":"from a distance, without being physically present, usually by using technology","acceptedParaphrases":["from a distance","without being there"],"masteryContexts":[{"contextId":"u2_17_remotely_meaning","text":"The engineer fixed the fault remotely without visiting the factory.","meaning":"from a distance using technology","wrongMeanings":["quickly using the right tools","carefully using a written plan","slowly using spare parts"]},{"contextId":"u2_17_remotely_paraphrase","text":"Students can attend the lecture remotely by video link.","meaning":"without being physically present","wrongMeanings":["without paying any fee at all","without taking notes of the lecture","without needing a teacher to speak"]}],"situationDistractors":["The technician drove to the office and repaired the server by hand.","All the staff met in the same room to discuss the plan.","The doctor examined the patient in the clinic.","The whole team sat around one table in the meeting room and discussed the budget.","The technician travelled to the factory and replaced the broken part with his own hands.","She visited her grandmother every Sunday and helped her to cook lunch in the kitchen."],"gapDistractors":[{"contextId":"u2_17_remotely_gap_1","answer":"remotely","wrong":["personally","locally","physically"]},{"contextId":"u2_17_remotely_gap_2","answer":"remotely","wrong":["locally","physically","personally"]},{"contextId":"u2_17_remotely_gap_3","answer":"remotely","wrong":["personally","physically","locally"]}],"spellingErrors":["remotly","remotley","remotelly","remoetly","rimotely","remotelie"],"masteryPassages":[{"passageId":"u2_17_remotely_passage_1","contextId":"u2_17_remotely_gap_1","text":"The engineer did not have to travel to the wind farm in the north. She repaired the fault ____, using a secure computer link from her office in the city.","answer":"remotely"},{"passageId":"u2_17_remotely_passage_2","contextId":"u2_17_remotely_gap_2","text":"During the heavy snow, the school was closed, but lessons did not stop. Students joined their classes ____ and could still ask the teacher questions on screen.","answer":"remotely"}],"contextDependentParaphrases":[],"wrongParaphrases":["in a hurry","by accident","in secret"],"misleadingDistractors":["very quickly and efficiently","in an unfriendly way","almost never"]}]'::jsonb,'[]'::jsonb,'["work remotely","controlled remotely","accessed remotely"]'::jsonb,'live'),
('vocab_transform','transform','verb','to change something completely, especially so that it becomes better or very different','[{"senseId":"transform_1","meaning":"to change something completely, especially so that it becomes better or very different","acceptedParaphrases":["change completely","turn into something new"],"masteryContexts":[{"contextId":"u2_18_transform_meaning","text":"The new park will transform the empty land into a green space.","meaning":"change completely into something different","wrongMeanings":["clean slightly and leave unchanged","protect from future damage","sell for more money"]},{"contextId":"u2_18_transform_paraphrase","text":"Technology can transform the way people learn.","meaning":"change in a big and important way","wrongMeanings":["copy exactly in a new place","slow down in a major way","explain in a simple way"]}],"situationDistractors":["The owner repainted one wall and left the rest of the shop the same.","The company moved its offices to a building across the road.","A small crack in the road was filled with tar.","The council repaired a few holes in the road and repainted the lines.","The shop changed its opening hours from nine o’clock to half past nine.","The students moved their desks closer to the window but left everything else in the classroom the same."],"gapDistractors":[{"contextId":"u2_18_transform_gap_1","answer":"transform","wrong":["describe","delay","repeat"]},{"contextId":"u2_18_transform_gap_2","answer":"transform","wrong":["describe","measure","copy"]},{"contextId":"u2_18_transform_gap_3","answer":"transform","wrong":["ignore","delay","repeat"]}],"spellingErrors":["transfrom","tranform","transfom","trasform","transferm","transforn"],"wordFamilyForms":[{"form":"transform","partOfSpeech":"verb","example":"A good teacher can transform a shy student into a confident speaker.","pedagogicallyUseful":true},{"form":"transformation","partOfSpeech":"noun","example":"The city has undergone a remarkable transformation in ten years.","pedagogicallyUseful":true,"altExample":"The caterpillar’s transformation into a butterfly takes several weeks."},{"form":"transformative","partOfSpeech":"adjective","example":"Many students describe the exchange year as a transformative experience.","pedagogicallyUseful":true,"altExample":"Online learning has had a transformative effect on rural schools.","note":"Moderately formal; flagged for teacher review."}],"masteryPassages":[{"passageId":"u2_18_transform_passage_1","contextId":"u2_18_transform_gap_1","text":"The old factory has stood empty for twenty years. The council plans to ____ it into a library, a café and a small theatre by next year.","answer":"transform"},{"passageId":"u2_18_transform_passage_2","contextId":"u2_18_transform_gap_2","text":"Some teachers believe that one inspiring lesson can ____ how a student feels about a whole subject. A pupil who once hated science may start to love it.","answer":"transform"}],"contextDependentParaphrases":[],"wrongParaphrases":["repeat often","improve slightly","destroy completely"],"misleadingDistractors":["move slowly from one place to another","repair slightly","copy exactly"]}]'::jsonb,'["transformation","transformative"]'::jsonb,'["transform lives","completely transform","transform society"]'::jsonb,'live'),
('vocab_percentage','percentage','noun','an amount expressed as a part of every hundred','[{"senseId":"percentage_1","meaning":"an amount expressed as a part of every hundred","acceptedParaphrases":["proportion","part of a hundred"],"masteryContexts":[{"contextId":"u2_19_percentage_meaning","text":"What percentage of the class walks to school?","meaning":"what part out of every hundred","wrongMeanings":["what total number of pupils there are","what average age the pupils have","what speed they walk at"]},{"contextId":"u2_19_percentage_paraphrase","text":"A small percentage of the profit goes to charity.","meaning":"a part of the whole, given as a number out of 100","wrongMeanings":["the length of time the profit is kept","the name of the charity that is chosen","the reason the profit was made"]}],"situationDistractors":["The teacher counted the total number of books on the shelf.","The class measured how fast each toy car rolled down the ramp.","The shop owner added the cost of all the items together.","The teacher wrote the date and the title on the board before the lesson began.","The class built a model bridge from paper and tested how much weight it could hold.","A group of pupils measured the length of the playground using a long measuring tape."],"gapDistractors":[{"contextId":"u2_19_percentage_gap_1","answer":"percentage","wrong":["speed","weight","height"]},{"contextId":"u2_19_percentage_gap_2","answer":"percentage","wrong":["speed","weight","distance"]},{"contextId":"u2_19_percentage_gap_3","answer":"percentage","wrong":["speed","distance","weight"]}],"spellingErrors":["percentege","precentage","percantage","percentge","pecentage","persentage"],"masteryPassages":[{"passageId":"u2_19_percentage_passage_1","contextId":"u2_19_percentage_gap_1","text":"The teacher told the class that only 15 of the 60 pupils had chosen chemistry. She asked them to work out what ____ that is of the whole group and to write it with a % sign.","answer":"percentage"},{"passageId":"u2_19_percentage_passage_2","contextId":"u2_19_percentage_gap_2","text":"The company promised to give some of its profits to charity. Critics asked what ____ of the money would be donated, since the announcement did not say whether it was 1% or 10%.","answer":"percentage"}],"contextDependentParaphrases":[],"wrongParaphrases":["total","average","difference"],"misleadingDistractors":["the total cost of something","the speed of a change","the average of two numbers"]}]'::jsonb,'[]'::jsonb,'["high percentage","small percentage","large percentage"]'::jsonb,'live'),
('vocab_impression','impression','noun','the idea or feeling you have about someone or something after seeing or meeting them','[{"senseId":"impression_1","meaning":"the idea or feeling you have about someone or something after seeing or meeting them","acceptedParaphrases":["first opinion","general feeling"],"masteryContexts":[{"contextId":"u2_20_impression_meaning","text":"The politician made a strong impression on the audience.","meaning":"a strong effect on what people think of someone","wrongMeanings":["a strong argument for changing the law","a strong reaction against a bad idea","a strong promise to improve the town"]},{"contextId":"u2_20_impression_paraphrase","text":"I had the impression that nobody was listening.","meaning":"a feeling or belief about what is true","wrongMeanings":["a proof that something is true","a rule that everyone must follow","a memory of an earlier lesson"]}],"situationDistractors":["He made a final decision after weighing all the evidence for several days.","The reporter wrote a long report about the school budget.","The two neighbours argued loudly about a fence.","He read the instructions twice and then put the furniture together in under an hour.","The two friends compared their timetables and planned a time to revise together.","The council repaired the old bridge and reopened it to traffic last week."],"gapDistractors":[{"contextId":"u2_20_impression_gap_1","answer":"impression","wrong":["report","plan","contract"]},{"contextId":"u2_20_impression_gap_2","answer":"impression","wrong":["excuse","plan","copy"]},{"contextId":"u2_20_impression_gap_3","answer":"impression","wrong":["photograph","visit","map"]}],"spellingErrors":["impresion","impresssion","imprestion","impreshion","inpression","empression"],"wordFamilyForms":[{"form":"impression","partOfSpeech":"noun","example":"The photographs gave a false impression of the hotel.","pedagogicallyUseful":true},{"form":"impress","partOfSpeech":"verb","example":"She hoped to impress the judges with her speech.","pedagogicallyUseful":true,"altExample":"It is difficult to impress an audience that has heard everything before."},{"form":"impressed","partOfSpeech":"adjective","example":"The examiners were impressed by the quality of her essay.","pedagogicallyUseful":true,"altExample":"I was impressed by how quickly the team solved the problem."}],"masteryPassages":[{"passageId":"u2_20_impression_passage_1","contextId":"u2_20_impression_gap_1","text":"Tom wore a clean shirt, shook the interviewer’s hand and smiled. He knew that the first few minutes would decide what the panel thought of him, so he wanted to make a good ____.","answer":"impression"},{"passageId":"u2_20_impression_passage_2","contextId":"u2_20_impression_gap_2","text":"The streets were quiet and the shops were closing early. I got the ____ that most people in the town had gone away for the holidays.","answer":"impression"}],"contextDependentParaphrases":[],"wrongParaphrases":["final decision","written report","public speech"],"misleadingDistractors":["a final decision","a written report","a strong disagreement"]}]'::jsonb,'["impress","impressed"]'::jsonb,'["good impression","first impression","lasting impression"]'::jsonb,'live')
